import {toIPA} from './ipa.js?v=6';
export function estimateWords(cue){const parts=[],words=[];let index=0;for(const match of cue.text.matchAll(/\[[^\]]*\]|>>|\p{L}+(?:['’]\p{L}+)*|\d+(?:[.,]\d+)*|[^\p{L}\d\[]+|\[/gu)){const text=match[0],annotation=/^\[|^>>$/.test(text),word=/^[\p{L}\d]/u.test(text);const part={text,ipa:annotation?'':word?toIPA(text).text:text,index:word?index++:-1};parts.push(part);if(word){const length=[...text].length;words.push({text,index:part.index,weight:Math.max(.7,Math.min(2.2,Math.sqrt(length)/1.7))});}else if(!annotation&&words.length&&/[,.!?;:]/.test(text)){words.at(-1).weight+=/[.!?]/.test(text)?.55:.25;}}
const total=words.reduce((sum,w)=>sum+w.weight,0),duration=Math.max(0,cue.end-cue.start);let elapsed=0;for(const word of words){word.start=cue.start+(total?elapsed/total*duration:0);elapsed+=word.weight;word.end=cue.start+(total?elapsed/total*duration:0);}if(words.length)words.at(-1).end=cue.end;return {parts,words};}
export function currentWord(words,time){if(!words.length||time<words[0].start||time>=words.at(-1).end)return -1;let low=0,high=words.length-1;while(low<high){const middle=Math.floor((low+high)/2);if(time<words[middle].end)high=middle;else low=middle+1;}return low;}
